<?php
declare(strict_types=1);require __DIR__.'/workflow-core.php';trackingHeaders();header('Content-Type: application/json; charset=utf-8');
if(($_SERVER['REQUEST_METHOD']??'')!=='POST'){http_response_code(405);exit;}
try{$input=json_decode((string)file_get_contents('php://input'),true);$found=workflowCustomerRecord((string)($input['token']??''));trackingLocked(function()use($found){$record=workflowProject(trackingRead($found['id']));if($record['stage']!=='Review')throw new InvalidArgumentException('Revision requests are available during Review.');$record['revisions_used']++;$record['updated_at']=gmdate('c');$record['revision']=bin2hex(random_bytes(16));workflowActivity($record,'revision_requested','Revision '.$record['revisions_used'].' of '.$record['revisions_included'].' requested.');trackingWrite($found['id'],$record);});echo json_encode(['ok'=>true]);}catch(OutOfBoundsException $e){http_response_code(404);echo json_encode(['error'=>'Link unavailable or expired.']);}catch(Throwable $e){http_response_code(422);echo json_encode(['error'=>$e->getMessage()]);}
